WITH mun AS (SELECT * FROM UNNEST(['2930766','2918100','2900355','2929701','2926509','2909208']) AS id_municipio),car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` JOIN mun USING(id_municipio) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),b AS (SELECT op.ano_emissao,c.id_imovel,c.id_municipio,c.area,op.id_referencia_bacen,op.id_programa,op.valor_parcela_credito/n.n_imoveis credito,op.area_financiada/n.n_imoveis area_financiada FROM p JOIN n USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao BETWEEN 2013 AND 2026 AND c.area<0.1),dp AS (SELECT DISTINCT chave,valor FROM `basedosdados.br_bcb_sicor.dicionario` WHERE nome_coluna='id_programa') SELECT b.id_municipio,COALESCE(dp.valor,CONCAT('código ',b.id_programa)) programa,COUNT(DISTINCT b.id_referencia_bacen) operacoes,COUNT(DISTINCT b.id_imovel) imoveis,SUM(b.credito) credito FROM b LEFT JOIN dp ON dp.chave=b.id_programa GROUP BY 1,2 ORDER BY b.id_municipio,credito DESC